# -*- coding: utf-8 -*-
"""Дополняет knowledge-кластер офлайн-знаниями (детерминированно, без сети).

knowledge.jsonl сейчас почти пуст (20 строк — только «Расскажи про книгу»).
Это добавит компактный базовый слой фактов (география, наука, история, ИТ,
общество), чтобы TF-IDF мог отвечать на распространённые «что такое...»,
не уходя в случайные фрагменты базы.

Запуск:  python scripts/build_knowledge.py
Идемпотентно: не дублирует уже существующие инструкции.
"""
import json, sys
from pathlib import Path

PROC = Path(r"D:\Mirro\data\processed")
KNOW = PROC / "knowledge.jsonl"

